
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_pbe1w_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_pbe1w", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.381782290960200e+00, -4.299143231928490e+00, -4.183425796014186e+00, -4.023297315834264e+00, -3.805461436867507e+00, -3.516306612931808e+00, -3.145767715134601e+00, -2.694193831858216e+00, -2.180899388680966e+00, -1.644221870036786e+00, -1.114768547763693e+00, -7.530624814468997e-01, -6.509506346503691e-01, -5.385860145755994e-01, -3.936911802416713e-01, -2.539996487411934e-01, -1.385252688273123e-01, -5.168469627719263e-02, -1.140687812953090e-02, -1.299428870749849e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


